/**
 * مزامنة بيانات الأوفلاين عند استئناف الاتصال.
 * يرفع الإيصالات والمبيعات المحلية إلى Firestore بنفس رقم العملية لتفادي التكرار والضياع.
 */

import { collection, addDoc, doc, setDoc, serverTimestamp, query, where, limit, getDocs, getDoc } from 'firebase/firestore';
import { Timestamp } from 'firebase/firestore';
import { auth, db } from '@/firebase';
import { userDataService } from '@/integrations/firebase/services';
import { syncPendingMerchantWalletsToFirestore } from '@/utils/pendingMerchantWalletsSync';
import walletDailyLimitsService from '@/utils/walletDailyLimitsService';

function parseLocalIsoMs(s: string): number {
  if (!s) return 0;
  const t = Date.parse(s);
  return Number.isFinite(t) ? t : 0;
}

/**
 * بعد إعادة فتح الشبكة: رفع أرصدة المستخدم وحدود المحافظ من التخزين المحلي إلى Firestore.
 * بدون ذلك تبقى قيم السيرفر قديمة ويستبدل الـ snapshot الواجهة (فيظهر الليميت والأرصدة كما قبل التأجيل).
 */
export async function flushHoldLocalBalancesAndLimitsToFirestore(userId: string): Promise<{
  balancesFlushed: boolean;
  limitsFlushed: number;
}> {
  let balancesFlushed = false;
  let limitsFlushed = 0;
  const ownerId = auth.currentUser?.uid || userId;

  type Cand = { cash: number; wallets: Record<string, number>; tsMs: number };
  const candidates: Cand[] = [];

  try {
    const rawUd = localStorage.getItem(`userData_${userId}`);
    if (rawUd) {
      const u = JSON.parse(rawUd) as any;
      if (
        u &&
        typeof u.cashBalance === 'number' &&
        u.walletBalances &&
        typeof u.walletBalances === 'object' &&
        !Array.isArray(u.walletBalances)
      ) {
        candidates.push({
          cash: Math.round(Number(u.cashBalance)),
          wallets: { ...u.walletBalances },
          tsMs: parseLocalIsoMs(String(u.lastUpdated || '')),
        });
      }
    }
  } catch {
    /* ignore */
  }

  try {
    const legW = localStorage.getItem(`walletBalances_${userId}`);
    const legC = localStorage.getItem(`cashBalance_${userId}`);
    if (legW && legC !== null) {
      const wallets = JSON.parse(legW);
      const cash = Math.round(Number(legC));
      if (Number.isFinite(cash) && typeof wallets === 'object' && wallets !== null && !Array.isArray(wallets)) {
        const tsMs = Math.max(
          parseLocalIsoMs(localStorage.getItem(`walletBalances_${userId}_lastUpdated`) || ''),
          parseLocalIsoMs(localStorage.getItem(`cashBalance_${userId}_lastUpdated`) || '')
        );
        candidates.push({ cash, wallets: { ...wallets }, tsMs });
      }
    }
  } catch {
    /* ignore */
  }

  const pW = `walletBalances_${userId}_`;
  const pC = `cashBalance_${userId}_`;
  try {
    for (let i = 0; i < localStorage.length; i++) {
      const k = localStorage.key(i);
      if (!k || !k.startsWith(pW) || k.endsWith('_lastUpdated')) continue;
      try {
        const wRaw = localStorage.getItem(k);
        const sid = k.slice(pW.length);
        const cRaw = localStorage.getItem(`${pC}${sid}`);
        if (!wRaw || cRaw === null) continue;
        const wallets = JSON.parse(wRaw);
        const cash = Math.round(Number(cRaw));
        if (!Number.isFinite(cash) || typeof wallets !== 'object' || wallets === null || Array.isArray(wallets)) continue;
        const tsW = localStorage.getItem(`${k}_lastUpdated`) || '';
        const tsC = localStorage.getItem(`${pC}${sid}_lastUpdated`) || '';
        const tsMs = Math.max(parseLocalIsoMs(tsW), parseLocalIsoMs(tsC));
        candidates.push({ cash, wallets: { ...wallets }, tsMs });
      } catch {
        continue;
      }
    }
  } catch {
    /* ignore */
  }

  if (candidates.length > 0) {
    const best = candidates.reduce((a, b) => (b.tsMs >= a.tsMs ? b : a));
    try {
      await userDataService.updateUserData(userId, {
        cashBalance: best.cash,
        walletBalances: best.wallets,
        lastUpdated: new Date().toISOString(),
      });
      balancesFlushed = true;
    } catch (e) {
      console.warn('flushHoldLocalBalances: updateUserData failed', e);
    }
  }

  const limPrefix = `walletLimits_${userId}_`;
  const n = (v: unknown, def = 0): number => {
    const x = Number(v);
    return Number.isFinite(x) ? x : def;
  };
  const capOr = (p: Record<string, unknown>, srv: Record<string, unknown>, key: string, def: number): number => {
    const lv = p[key];
    if (lv !== undefined && lv !== null && Number.isFinite(Number(lv))) return n(lv);
    const sv = srv[key];
    if (sv !== undefined && sv !== null && Number.isFinite(Number(sv))) return n(sv);
    return def;
  };
  const usedMax = (p: Record<string, unknown>, srv: Record<string, unknown>, key: string): number =>
    Math.max(n(p[key]), n(srv[key]));

  try {
    for (let i = 0; i < localStorage.length; i++) {
      const k = localStorage.key(i);
      if (!k || !k.startsWith(limPrefix)) continue;
      const walletId = k.slice(limPrefix.length);
      if (!walletId) continue;
      try {
        const raw = localStorage.getItem(k);
        if (!raw) continue;
        const p = JSON.parse(raw) as Record<string, unknown>;
        if (!p || typeof p !== 'object') continue;

        let srv: Record<string, unknown> = {};
        try {
          const limSnap = await getDoc(doc(db, 'walletLimits', walletId));
          if (limSnap.exists()) srv = (limSnap.data() as Record<string, unknown>) || {};
        } catch {
          /* ignore */
        }

        const periodDayKey =
          typeof p.periodDayKey === 'string' && p.periodDayKey
            ? p.periodDayKey
            : walletDailyLimitsService.getCurrentDayId();
        const periodMonthKey =
          typeof p.periodMonthKey === 'string' && p.periodMonthKey
            ? p.periodMonthKey
            : walletDailyLimitsService.getCurrentMonthId();

        await setDoc(
          doc(db, 'walletLimits', walletId),
          {
            dailyTransferLimit: capOr(p, srv, 'dailyTransferLimit', 60000),
            dailyWithdrawLimit: capOr(p, srv, 'dailyWithdrawLimit', 100000),
            dailyTransferUsed: usedMax(p, srv, 'dailyTransferUsed'),
            dailyWithdrawUsed: usedMax(p, srv, 'dailyWithdrawUsed'),
            monthlyTransferLimit: capOr(p, srv, 'monthlyTransferLimit', 200000),
            monthlyWithdrawLimit: capOr(p, srv, 'monthlyWithdrawLimit', 200000),
            monthlyTransferUsed: usedMax(p, srv, 'monthlyTransferUsed'),
            monthlyWithdrawUsed: usedMax(p, srv, 'monthlyWithdrawUsed'),
            periodDayKey,
            periodMonthKey,
            updatedAt: serverTimestamp(),
            ownerId,
          },
          { merge: true }
        );
        limitsFlushed++;
      } catch (e) {
        console.warn('flushHoldLocalLimits: wallet', walletId, e);
      }
    }
  } catch {
    /* ignore */
  }

  return { balancesFlushed, limitsFlushed };
}

interface SaleItemLike {
  id: string;
  firestoreId?: string;
  productName: string;
  price?: number;
  wholesalePrice?: number;
  quantity?: number;
  date?: string;
  time?: string;
  serialNumber?: string;
  barcode?: string;
  isDeferred?: boolean;
  paymentMethod?: 'cash' | 'visa';
  customerName?: string;
  customerMobile?: string;
  customerId?: string;
  cartItems?: Array<{ productId: string; productName: string; quantity: number; price: number; wholesalePrice?: number; barcode?: string }>;
  imageBase64?: string;
  createdAtMs?: number;
}

interface SyncResult {
  receiptsSynced: number;
  receiptsFailed: number;
  salesSynced: number;
  salesFailed: number;
  balancesFlushed: boolean;
  limitsFlushed: number;
  pendingWalletsSynced: number;
  pendingWalletsFailed: number;
}

async function saveSaleToFirestore(
  userId: string,
  shopId: string | null,
  sale: SaleItemLike,
  performedByName: string
): Promise<string | null> {
  const profit = ((sale.price ?? 0) - (sale.wholesalePrice ?? 0)) * (sale.quantity ?? 1);
  const createdAtValue =
    sale.createdAtMs != null ? Timestamp.fromMillis(sale.createdAtMs) : serverTimestamp();
  const saleMoment = sale.createdAtMs != null ? new Date(sale.createdAtMs) : new Date();
  const dateForStorage = new Intl.DateTimeFormat('en-CA', { timeZone: 'Africa/Cairo' }).format(saleMoment);
  const payload: Record<string, unknown> = {
    userId,
    clientId: sale.id,
    productName: sale.productName,
    quantity: sale.quantity ?? 0,
    wholesalePrice: sale.wholesalePrice ?? null,
    sellingPrice: sale.price ?? 0,
    profit,
    date: dateForStorage,
    time: sale.time ?? '',
    performedByType: 'admin',
    performedByName,
    performedByUsername: null,
    serialNumber: sale.serialNumber ?? null,
    barcode: sale.barcode ?? null,
    isDeferred: !!sale.isDeferred,
    paymentMethod: sale.paymentMethod || 'cash',
    customerName: sale.customerName ?? null,
    customerMobile: sale.customerMobile ?? null,
    customerId: sale.customerId ?? null,
    ...(shopId ? { shopId } : {}),
    ...(sale.cartItems ? { cartItems: sale.cartItems } : {}),
    ...(sale.imageBase64 ? { imageBase64: sale.imageBase64 } : {}),
    createdAt: createdAtValue,
  };
  try {
    const docRef = await addDoc(collection(db, 'dailySales'), payload);
    try {
      await setDoc(doc(db, 'users', userId, 'dailySales', docRef.id), { ...payload });
    } catch {
      /* secondary path best-effort */
    }
    return docRef.id;
  } catch {
    try {
      const docRef2 = await addDoc(collection(db, 'users', userId, 'dailySales'), payload);
      try {
        await setDoc(doc(db, 'dailySales', docRef2.id), { ...payload });
      } catch {}
      return docRef2.id;
    } catch {
      return null;
    }
  }
}

function getSalesKeysForUser(userId: string): string[] {
  const keys: string[] = [];
  try {
    for (let i = 0; i < localStorage.length; i++) {
      const k = localStorage.key(i);
      if (k && k.startsWith(`salesData_all_${userId}_`)) keys.push(k);
    }
  } catch {}
  return keys;
}

async function syncUnsyncedSales(
  userId: string,
  shopId: string | null,
  performedByName: string
): Promise<{ synced: number; failed: number }> {
  let synced = 0;
  let failed = 0;
  const keys = getSalesKeysForUser(userId);
  for (const storageKey of keys) {
    try {
      const raw = localStorage.getItem(storageKey);
      if (!raw) continue;
      const arr = JSON.parse(raw) as SaleItemLike[];
      if (!Array.isArray(arr)) continue;
      const unsynced = arr.filter((s) => !s.firestoreId && s.id);
      if (unsynced.length === 0) continue;
      for (const sale of unsynced) {
        try {
          const existingQ = shopId
            ? query(
                collection(db, 'dailySales'),
                where('userId', '==', userId),
                where('shopId', '==', shopId),
                where('clientId', '==', sale.id),
                limit(1)
              )
            : query(
                collection(db, 'dailySales'),
                where('userId', '==', userId),
                where('clientId', '==', sale.id),
                limit(1)
              );
          const existingSnap = await getDocs(existingQ);
          if (!existingSnap.empty) {
            const docId = existingSnap.docs[0].id;
            const updated = arr.map((s) => (s.id === sale.id ? { ...s, firestoreId: docId } : s));
            localStorage.setItem(storageKey, JSON.stringify(updated));
            synced++;
            continue;
          }
          const docId = await saveSaleToFirestore(userId, shopId, sale, performedByName);
          if (docId) {
            const updated = arr.map((s) => (s.id === sale.id ? { ...s, firestoreId: docId } : s));
            localStorage.setItem(storageKey, JSON.stringify(updated));
            synced++;
          } else {
            failed++;
          }
        } catch {
          failed++;
        }
      }
    } catch (e) {
      console.warn('offlineSync: sync sales for key', storageKey, e);
    }
  }
  return { synced, failed };
}

/**
 * مزامنة كل البيانات المحلية (إيصالات + مبيعات) عند استئناف الاتصال.
 * يُستدعى من ProfileSettingsPage بعد waitForPendingWrites (لا enableNetwork — يتعارض مع مستمعات Firestore).
 */
export async function offlineSyncOnResume(
  userId: string,
  options?: { shopId?: string | null; performedByName?: string }
): Promise<SyncResult> {
  const shopId = options?.shopId ?? null;
  const performedByName = options?.performedByName ?? 'الحساب الرئيسي';
  /** بعد رفع الإيصالات/المبيعات حتى لا تُستبدل قيم الليميت المحلية بكتابات قديمة من الطابور. */
  const receipts = await userDataService.syncLocalReceiptsToFirestore(userId);
  const sales = await syncUnsyncedSales(userId, shopId, performedByName);
  const pendingWallets = await syncPendingMerchantWalletsToFirestore(userId);
  const flush = await flushHoldLocalBalancesAndLimitsToFirestore(userId);
  try {
    if (typeof window !== 'undefined') {
      window.dispatchEvent(new CustomEvent('cashyOfflineHoldFlushed', { detail: { userId } }));
    }
  } catch {
    /* ignore */
  }
  return {
    receiptsSynced: receipts.synced,
    receiptsFailed: receipts.failed,
    salesSynced: sales.synced,
    salesFailed: sales.failed,
    balancesFlushed: flush.balancesFlushed,
    limitsFlushed: flush.limitsFlushed,
    pendingWalletsSynced: pendingWallets.synced,
    pendingWalletsFailed: pendingWallets.failed,
  };
}
