/**
 * محافظ أُضيفت أثناء تأجيل Firestore (أوفلاين): تُحفظ محلياً ثم تُرفع عند استئناف الشبكة.
 */

export const HOLD_WALLET_ID_PREFIX = 'holdw_';

export function makeHoldWalletId(): string {
  return `${HOLD_WALLET_ID_PREFIX}${Date.now()}_${Math.random().toString(36).slice(2, 10)}`;
}

function pendingKey(userId: string): string {
  return `pendingMerchantWallets_${userId}`;
}

export type PendingMerchantWalletEntry = {
  offlineId: string;
  payload: Record<string, unknown>;
  limits: {
    dailyTransferLimit: number;
    dailyWithdrawLimit: number;
    monthlyTransferLimit: number;
    monthlyWithdrawLimit: number;
  };
};

export function pushPendingMerchantWallet(userId: string, entry: PendingMerchantWalletEntry): void {
  try {
    const k = pendingKey(userId);
    const cur = JSON.parse(localStorage.getItem(k) || '[]');
    const list = Array.isArray(cur) ? cur : [];
    list.push(entry);
    localStorage.setItem(k, JSON.stringify(list));
  } catch {
    /* ignore */
  }
}

/** محافظ محلية بمعرف holdw_ من أي مفتاح wallets_${userId}* */
export function listHoldWalletsFromLocalStorage(userId: string): any[] {
  const out: any[] = [];
  const seen = new Set<string>();
  try {
    for (let i = 0; i < localStorage.length; i++) {
      const k = localStorage.key(i);
      if (!k || !k.startsWith(`wallets_${userId}`)) continue;
      const raw = localStorage.getItem(k);
      if (!raw) continue;
      let arr: unknown;
      try {
        arr = JSON.parse(raw);
      } catch {
        continue;
      }
      if (!Array.isArray(arr)) continue;
      for (const w of arr) {
        const id = String((w as any)?.id || '');
        if (!id.startsWith(HOLD_WALLET_ID_PREFIX)) continue;
        if (seen.has(id)) continue;
        seen.add(id);
        out.push(w);
      }
    }
  } catch {
    /* ignore */
  }
  return out;
}

/**
 * دمج محافظ السيرفر مع محافظ holdw_ المحلية (بدون تكرار id أو نفس رقم الهاتف).
 */
export function mergeHoldWalletsIntoList<T extends { id: string; phone?: string }>(
  serverWallets: T[],
  userId: string,
  mapLocal: (w: any) => T
): T[] {
  const byId = new Set(serverWallets.map((w) => String(w.id)));
  const byPhone = new Set(
    serverWallets.map((w) => String(w.phone || '').replace(/\D/g, '')).filter(Boolean)
  );
  const locals = listHoldWalletsFromLocalStorage(userId);
  const extras: T[] = [];
  for (const w of locals) {
    const id = String(w?.id || '');
    if (!id.startsWith(HOLD_WALLET_ID_PREFIX)) continue;
    if (byId.has(id)) continue;
    const pn = String(w.phone || '').replace(/\D/g, '');
    if (pn && byPhone.has(pn)) continue;
    byId.add(id);
    if (pn) byPhone.add(pn);
    extras.push(mapLocal(w));
  }
  return [...serverWallets, ...extras];
}

export function migrateWalletIdInLocalStorage(userId: string, offlineId: string, realId: string): void {
  if (!userId || !offlineId || !realId || offlineId === realId) return;
  try {
    for (let i = 0; i < localStorage.length; i++) {
      const k = localStorage.key(i);
      if (!k) continue;

      if (k.startsWith(`wallets_${userId}`)) {
        const raw = localStorage.getItem(k);
        if (!raw) continue;
        try {
          const arr = JSON.parse(raw);
          if (!Array.isArray(arr)) continue;
          let changed = false;
          const next = arr.map((w: any) => {
            if (w && String(w.id) === offlineId) {
              changed = true;
              return { ...w, id: realId };
            }
            return w;
          });
          if (changed) localStorage.setItem(k, JSON.stringify(next));
        } catch {
          continue;
        }
      }

      if (k === `walletLimits_${userId}_${offlineId}`) {
        const raw = localStorage.getItem(k);
        if (raw) {
          localStorage.setItem(`walletLimits_${userId}_${realId}`, raw);
          localStorage.removeItem(k);
        }
      }

      if (k.startsWith(`selectedWallet_${userId}_`) && localStorage.getItem(k) === offlineId) {
        localStorage.setItem(k, realId);
      }
    }

    const udKey = `userData_${userId}`;
    const udRaw = localStorage.getItem(udKey);
    if (udRaw) {
      try {
        const ud = JSON.parse(udRaw) as any;
        if (ud?.walletBalances && typeof ud.walletBalances === 'object' && offlineId in ud.walletBalances) {
          const wb = { ...ud.walletBalances };
          wb[realId] = wb[offlineId];
          delete wb[offlineId];
          localStorage.setItem(udKey, JSON.stringify({ ...ud, walletBalances: wb }));
        }
      } catch {
        /* ignore */
      }
    }

    const wbKey = `walletBalances_${userId}`;
    const wbRaw = localStorage.getItem(wbKey);
    if (wbRaw) {
      try {
        const wb = JSON.parse(wbRaw) as Record<string, number>;
        if (wb && typeof wb === 'object' && offlineId in wb) {
          const next = { ...wb };
          next[realId] = next[offlineId];
          delete next[offlineId];
          localStorage.setItem(wbKey, JSON.stringify(next));
        }
      } catch {
        /* ignore */
      }
    }

    const p = `walletBalances_${userId}_`;
    for (let j = 0; j < localStorage.length; j++) {
      const key2 = localStorage.key(j);
      if (!key2 || !key2.startsWith(p) || key2.endsWith('_lastUpdated')) continue;
      const raw2 = localStorage.getItem(key2);
      if (!raw2) continue;
      try {
        const wb = JSON.parse(raw2) as Record<string, number>;
        if (wb && typeof wb === 'object' && offlineId in wb) {
          const next = { ...wb };
          next[realId] = next[offlineId];
          delete next[offlineId];
          localStorage.setItem(key2, JSON.stringify(next));
        }
      } catch {
        /* ignore */
      }
    }
  } catch {
    /* ignore */
  }
}

export async function syncPendingMerchantWalletsToFirestore(userId: string): Promise<{ synced: number; failed: number }> {
  const key = pendingKey(userId);
  let list: PendingMerchantWalletEntry[] = [];
  try {
    const parsed = JSON.parse(localStorage.getItem(key) || '[]');
    list = Array.isArray(parsed) ? parsed : [];
  } catch {
    return { synced: 0, failed: 0 };
  }
  if (list.length === 0) return { synced: 0, failed: 0 };

  const { merchantWalletService } = await import('@/integrations/firebase/services');
  const { walletDailyLimitsService } = await import('@/utils/walletDailyLimitsService');

  const remaining: PendingMerchantWalletEntry[] = [];
  let synced = 0;
  let failed = 0;

  for (const item of list) {
    if (!item?.offlineId || !item?.payload) {
      failed++;
      continue;
    }
    try {
      const realId = await merchantWalletService.create(item.payload as any);
      if (item.limits) {
        await walletDailyLimitsService.setLimits(realId, item.limits);
      }
      migrateWalletIdInLocalStorage(userId, item.offlineId, realId);
      synced++;
    } catch (e) {
      console.warn('syncPendingMerchantWalletsToFirestore:', item.offlineId, e);
      failed++;
      remaining.push(item);
    }
  }

  try {
    localStorage.setItem(key, JSON.stringify(remaining));
  } catch {
    /* ignore */
  }

  return { synced, failed };
}
